import { useAccordion } from '@dreadnought/react/logic';
export function Example() {
  const { value, toggle } = useAccordion({});
  return <><button aria-expanded={value === 'install'} aria-controls="install" onClick={() => toggle('install')}>Установка</button><div id="install" hidden={value !== 'install'}>Инструкция</div></>;
}

import { AccordionAdapter } from '@dreadnought/react/unstyled';
export function Example() {
  return <AccordionAdapter><AccordionAdapter.Item value="install"><AccordionAdapter.Trigger>Как установить?</AccordionAdapter.Trigger><AccordionAdapter.Panel>Установите пакет и импортируйте компонент.</AccordionAdapter.Panel></AccordionAdapter.Item></AccordionAdapter>;
}
